new='''/// Where the lexer is within a line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: expecting a timestamp, a key or a word.
    Item,
    /// Right after a `key=`: expecting its value.
    Value,
    /// After an error: nothing more is produced.
    Failed,
}

type Lexed<'a> = Result<Token<'a>, LexError>;

#[inline(always)]
fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\\t'
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Item }
    }

    #[inline(always)]
    fn bytes(&self) -> &'a [u8] {
        self.src.as_bytes()
    }

    /// Stops the stream with `err`.
    #[cold]
    fn fail(&mut self, err: LexError) -> Lexed<'a> {
        self.state = State::Failed;
        self.pos = self.src.len();
        Err(err)
    }

    /// A token must be followed by a blank or the end of the line.
    #[inline(always)]
    fn check_separator(&mut self, end: usize) -> Result<(), Lexed<'a>> {
        match self.bytes().get(end) {
            Some(&c) if !is_blank(c) => Err(self.fail(LexError::ExpectedSeparator { pos: end })),
            _ => Ok(()),
        }
    }

    /// `[timestamp]`, starting at the `[` at `start`.
    fn timestamp(&mut self, start: usize) -> Lexed<'a> {
        let b = self.bytes();
        let body = start + 1;
        let mut i = body;
        loop {
            match b.get(i) {
                None => return self.fail(LexError::UnterminatedTimestamp { pos: start }),
                Some(b']') => break,
                Some(b'[') => return self.fail(LexError::NestedBracket { pos: i }),
                Some(_) => i += 1,
            }
        }
        if let Err(e) = self.check_separator(i + 1) {
            return e;
        }
        self.pos = i + 1;
        Ok(Token::Timestamp(&self.src[body..i]))
    }

    /// A `key=` (leaving the value pending) or a standalone word, starting at `start`.
    fn key_or_word(&mut self, start: usize) -> Lexed<'a> {
        let b = self.bytes();
        let mut i = start;
        while let Some(&c) = b.get(i) {
            if is_blank(c) || c == b'=' {
                break;
            }
            if c == b'"' {
                return self.fail(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        let text = &self.src[start..i];
        if b.get(i) == Some(&b'=') {
            self.state = State::Value;
            self.pos = i + 1;
            Ok(Token::Key(text))
        } else {
            self.pos = i;
            Ok(Token::Word(text))
        }
    }

    /// A double-quoted value, starting at the opening quote at `start`.
    fn quoted(&mut self, start: usize) -> Lexed<'a> {
        let b = self.bytes();
        let body = start + 1;
        let mut i = body;
        loop {
            match b.get(i) {
                None => return self.fail(LexError::UnterminatedQuote { pos: start }),
                Some(b'"') => break,
                Some(b'\\\\') => match b.get(i + 1) {
                    None => return self.fail(LexError::UnterminatedQuote { pos: start }),
                    Some(b'"' | b'\\\\' | b'n' | b't') => i += 2,
                    Some(_) => return self.fail(LexError::InvalidEscape { pos: i }),
                },
                Some(_) => i += 1,
            }
        }
        if let Err(e) = self.check_separator(i + 1) {
            return e;
        }
        self.state = State::Item;
        self.pos = i + 1;
        Ok(Token::Quoted(&self.src[body..i]))
    }

    /// An unquoted value, starting at `start`.
    fn bare(&mut self, start: usize) -> Lexed<'a> {
        let b = self.bytes();
        let mut i = start;
        while let Some(&c) = b.get(i) {
            if is_blank(c) {
                break;
            }
            if c == b'"' {
                return self.fail(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        self.state = State::Item;
        self.pos = i;
        Ok(Token::Bare(&self.src[start..i]))
    }

    /// Next item: timestamp, key or word.
    fn item(&mut self) -> Option<Lexed<'a>> {
        let b = self.bytes();
        let mut p = self.pos;
        while p < b.len() && is_blank(b[p]) {
            p += 1;
        }
        self.pos = p;
        Some(match b.get(p)? {
            b'[' => self.timestamp(p),
            b'"' => self.fail(LexError::UnexpectedQuote { pos: p }),
            b'=' => self.fail(LexError::EmptyKey { pos: p }),
            _ => self.key_or_word(p),
        })
    }

    /// The value after a key; may be empty.
    fn value(&mut self) -> Lexed<'a> {
        let p = self.pos;
        match self.bytes().get(p) {
            None => self.empty_value(p),
            Some(&c) if is_blank(c) => self.empty_value(p),
            Some(b'"') => self.quoted(p),
            Some(_) => self.bare(p),
        }
    }

    fn empty_value(&mut self, at: usize) -> Lexed<'a> {
        self.state = State::Item;
        Ok(Token::Bare(&self.src[at..at]))
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Lexed<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        match self.state {
            State::Item => self.item(),
            State::Value => Some(self.value()),
            State::Failed => None,
        }
    }
}
