    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Where the lexer is within a line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: expecting a timestamp, a key or a word.
    Item,
    /// Right after a `key=`: expecting its value.
    Value,
    /// After an error: nothing more is produced.
    Failed,
}

type Lexed<'a> = Result<Token<'a>, LexError>;

#[inline(always)]
fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

